document.querySelector('#excel-import').addEventListener('change',async event=>{event.preventDefault();event.stopImmediatePropagation();const file=event.target.files[0];event.target.value='';if(!file||!window.XLSX)return;try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:''});let imported=0,skipped=0;rows.forEach(row=>{const name=String(findColumn(row,['product','item','productname','itemname','description'])).trim(),category=String(findColumn(row,['category','group','productcategory'])).trim()||'Uncategorized',code=String(findColumn(row,['code','sku','itemcode','productcode'])).trim(),variant=String(findColumn(row,['variant','size','finish','sizefinish','sizevariant','model'])).trim()||'Standard',stock=Math.max(0,Number(findColumn(row,['stock','qty','quantity','pieces','closingstock','openingstock']))||0),price=Math.max(0,Number(findColumn(row,['price','rate','unitprice','priceperpiece','mrp','cost']))||0),min=Math.max(0,Number(findColumn(row,['minimum','minstock','minimumstock','alert','alertat']))||0);if(!name){skipped++;return}let product=code&&products.find(item=>String(item.code||'').toLowerCase()===code.toLowerCase());if(!product)product=products.find(item=>item.name.toLowerCase()===name.toLowerCase()&&String(item.variant||'').toLowerCase()===variant.toLowerCase());if(product){const before=product.stock,oldPrice=product.price||0;product.name=name;product.category=category;product.code=code||product.code||`SKU-${Date.now()}-${imported}`;product.variant=variant;product.price=price||oldPrice;product.min=min;product.stock+=stock;if(price&&price!==oldPrice)recordPriceChange(product,oldPrice,price,'Excel import');activity.unshift({type:'in',product:product.name,category,code:product.code,variant,price:price||oldPrice,transactionPrice:price||oldPrice,qty:stock,beforeStock:before,afterStock:product.stock,stockChange:stock,ref:'Excel import - updated by SKU',time:'Just now'})}else{product={id:Date.now()+imported,name,category,code:code||`SKU-${Date.now()}-${imported}`,variant,stock,price,min};products.push(product);activity.unshift({type:'in',product:name,category,code:product.code,variant,price,transactionPrice:price,qty:stock,beforeStock:0,afterStock:stock,stockChange:stock,ref:'Excel import - new product',time:'Just now'})}imported++});save();render();showToast(`${imported} products imported${skipped?`, ${skipped} rows skipped`:''}`,'success')}catch(error){showToast('Excel import failed. Check the template columns.','error')}},true);
function downloadImportTemplate(){const headers=['Product','Category','SKU','Size / Variant','Opening Stock','Price','Minimum Stock'];const sample=['Tower Bolt','Tower Bolt','142A','9mm Stainless Steel',100,245,20];if(window.XLSX){const workbook=XLSX.utils.book_new(),template=XLSX.utils.aoa_to_sheet([headers,sample]),instructions=XLSX.utils.aoa_to_sheet([['Column','What to enter'],['Product','Product name, required'],['Category','Category or product group'],['SKU','Unique product code'],['Size / Variant','Size, finish, model or variant'],['Opening Stock','Whole number of starting pieces'],['Price','Current price per piece'],['Minimum Stock','Alert threshold in pieces']]);XLSX.utils.book_append_sheet(workbook,template,'Import Template');XLSX.utils.book_append_sheet(workbook,instructions,'Instructions');XLSX.writeFile(workbook,'godown-stock-import-template.xlsx');return}const csv=[headers,sample].map(row=>row.join(',')).join('\r\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='godown-stock-import-template.csv';link.click();}
document.addEventListener('click',e=>{if(e.target.closest('#download-template'))downloadImportTemplate()},true);
function enhanceOverviewSearch(){if(currentView!=='overview')return;const panel=document.querySelector('.content-grid .panel:first-child'),head=panel?.querySelector('.panel-head'),wrap=panel?.querySelector('.table-wrap');if(!head||!wrap)return;if(!panel.querySelector('.overview-category-summary')){const summary=document.createElement('div');summary.className='overview-category-summary';summary.innerHTML=categoryStockSummary(products).replace('category-stock-summary','overview-category-summary-inner');panel.insertBefore(summary,wrap)}if(head.querySelector('#overview-quick-search'))return;const search=document.createElement('input');search.id='overview-quick-search';search.className='quick-search';search.type='search';search.placeholder='Search SKU or size...';search.setAttribute('aria-label','Quick search inventory');head.insertBefore(search,head.querySelector('[data-go]'));const update=()=>{const term=search.value.trim().toLowerCase();const matches=products.filter(p=>`${p.name} ${p.category||''} ${p.code||''} ${p.variant||''}`.toLowerCase().includes(term));wrap.innerHTML=matches.length?`<table class="data-table"><thead><tr><th>Product / variant</th><th>Available</th><th>Alert at</th><th>Status</th></tr></thead><tbody>${productRows(matches.slice(0,5))}</tbody></table>`:`<div class="empty">No matching products found</div>`;};search.addEventListener('input',update);}
