let undoDelete=null;
document.addEventListener('click',e=>{if(!e.target.closest('#confirm-delete'))return;e.preventDefault();e.stopImmediatePropagation();const removed=products.find(item=>item.id===pendingDeleteId);if(!removed)return;products=products.filter(item=>item.id!==pendingDeleteId);const deleteLog={type:'delete',product:removed.name,variant:removed.variant,qty:removed.stock,ref:`Deleted by ${currentRole==='admin'?'Owner':'Entry Staff'}`,time:'Just now'};activity.unshift(deleteLog);undoDelete={product:removed,activity:deleteLog};save();$('#delete-modal').classList.add('hidden');render();showToast('Product deleted. Press Ctrl+Z to undo.','info')},true);
