document.querySelector('#excel-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||!window.XLSX)return;try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:''}),seen=new Set(),duplicates=[];rows.forEach(row=>{const sku=String(findColumn(row,['code','sku','itemcode','productcode'])).trim().toLowerCase();if(sku&&(seen.has(sku)||products.some(p=>String(p.code||'').toLowerCase()===sku)))duplicates.push(sku);seen.add(sku)});if(duplicates.length)showToast(`${duplicates.length} duplicate SKU row(s) detected. Existing items will be matched, not duplicated.`,'info')}catch(error){showToast('Import preview could not be read.','error')}},true);
