const nativeAlert = window.alert.bind(window);
window.alert = message => { if(typeof showToast === 'function') showToast(String(message), 'info'); else nativeAlert(message); };
function showToast(message,type='info'){const region=document.querySelector('#toast-region');if(!region)return nativeAlert(message);const toast=document.createElement('div');toast.className=`toast ${type}`;toast.textContent=message;region.appendChild(toast);setTimeout(()=>toast.remove(),4200);}
function enhanceInventory(){const search=document.querySelector('#inventory-search'),body=document.querySelector('#inventory-body'),sort=document.querySelector('#inventory-sort'),pageSize=document.querySelector('#inventory-page-size'),pageLabel=document.querySelector('#inventory-page-label'),previous=document.querySelector('#inventory-prev'),next=document.querySelector('#inventory-next'),bulkMin=document.querySelector('#bulk-min'),bulkApply=document.querySelector('#bulk-apply');if(!search||!body)return;let page=1;const update=()=>{const term=search.value.toLowerCase(),filter=document.querySelector('#stock-filter')?.value||'all',size=Number(pageSize?.value||10);let list=products.filter(p=>(`${p.name} ${p.category||''} ${p.code||''} ${p.variant||''}`).toLowerCase().includes(term)).filter(p=>filter==='all'||(filter==='low'?p.stock<=p.min:p.stock>p.min));const mode=sort?.value||'name';list.sort((a,b)=>mode==='stock'?b.stock-a.stock:mode==='price'?(b.price||0)-(a.price||0):mode==='category'?(a.category||'').localeCompare(b.category||''):a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(list.length/size));page=Math.min(page,pages);const visible=list.slice((page-1)*size,page*size);body.innerHTML=productRows(visible);if(pageLabel)pageLabel.textContent=`Page ${page} of ${pages} · ${list.length} products`;if(previous)previous.disabled=page===1;if(next)next.disabled=page===pages;};search.oninput=()=>{page=1;update()};document.querySelector('#stock-filter')?.addEventListener('change',()=>{page=1;update()});sort?.addEventListener('change',()=>{page=1;update()});pageSize?.addEventListener('change',()=>{page=1;update()});previous?.addEventListener('click',()=>{page--;update()});next?.addEventListener('click',()=>{page++;update()});bulkApply?.addEventListener('click',()=>{const value=Number(bulkMin?.value);if(!Number.isInteger(value)||value<0)return showToast('Enter a valid alert threshold.','error');const term=search.value.toLowerCase();products.filter(p=>(`${p.name} ${p.category||''} ${p.code||''} ${p.variant||''}`).toLowerCase().includes(term)).forEach(p=>p.min=value);save();render();showToast('Alert threshold updated for matching products.','success')});update();}
inventory=function(){return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">PRODUCT MASTER · PIECES ONLY</div><h2>Inventory</h2></div>${movementActions()}</div><div class="inventory-tools"><input id="inventory-search" placeholder="Search product, category, SKU or finish..." aria-label="Search inventory"/><select class="filter-select" id="stock-filter"><option value="all">All stock</option><option value="low">Low stock</option><option value="ok">In stock</option></select><select class="filter-select" id="inventory-sort" aria-label="Sort inventory"><option value="name">Sort: Product</option><option value="stock">Sort: Stock</option><option value="price">Sort: Price</option><option value="category">Sort: Category</option></select><select class="filter-select" id="inventory-page-size" aria-label="Products per page"><option value="10">10 / page</option><option value="25">25 / page</option><option value="50">50 / page</option></select></div><div class="bulk-bar"><span>Bulk alert threshold</span><input id="bulk-min" type="number" min="0" placeholder="pieces"/><button id="bulk-apply" type="button">Apply to search results</button></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Product / category / variant</th><th>Available pieces</th><th>Alert threshold</th><th>Status</th></tr></thead><tbody id="inventory-body">${products.length?productRows(products.slice(0,10)):`<tr><td colspan="4">${emptyInventory()}</td></tr>`}</tbody></table></div><div class="pagination"><span id="inventory-page-label">Page 1</span><div><button id="inventory-prev" type="button">← Previous</button> <button id="inventory-next" type="button">Next →</button></div></div></div></section>`};
