exportReport=function(){const r=reportRows(),rows=[['SECTION','PRODUCTS'],['Product','Category','SKU','Size / Variant','Current Price','Stock','Minimum'],...products.map(p=>[p.name,p.category||'Uncategorized',p.code||'',p.variant||'',p.price||0,p.stock,p.min]),[],['SECTION','PRICE HISTORY'],['Product','Old Price','New Price','Changed By','Changed Date','Reason'],...priceHistory.map(h=>[h.product,h.oldPrice,h.newPrice,h.changedBy,h.changedAt,h.reason]),[],['SECTION','PURCHASES'],['Product','Supplier / Reference','Transaction Price','Quantity','Date'],...r.purchases.map(a=>[a.product,a.ref||'',a.transactionPrice??a.price??0,a.qty||0,a.createdAt||a.time||'']),[],['SECTION','SALES'],['Product','Customer / Reference','Transaction Price','Quantity','Date'],...r.sales.map(a=>[a.product,a.ref||'',a.transactionPrice??a.price??0,a.qty||0,a.createdAt||a.time||'']),[],['SECTION','CATEGORY STOCK'],['Category','Pieces'],...Object.entries(r.byCategory),[],['SECTION','SUPPLIER PURCHASES'],['Supplier','Pieces'],...Object.entries(r.bySupplier),[],['SECTION','LOW STOCK'],['Product','Stock','Minimum'],...r.low.map(p=>[p.name,p.stock,p.min]),[],['SECTION','OUT OF STOCK'],['Product','Stock','Minimum'],...r.out.map(p=>[p.name,p.stock,p.min]),[],['SECTION','FAST MOVING'],['Product','Sold Pieces'],...r.fast.map(p=>[p.name,activity.filter(a=>a.product===p.name&&a.type==='out').reduce((s,a)=>s+(a.qty||0),0)]),[],['SECTION','SLOW MOVING'],['Product','Sales Count'],...r.slow.map(p=>[p.name,activity.filter(a=>a.product===p.name&&a.type==='out').length]),[],['SECTION','DEAD STOCK'],['Product','Stock'],...r.dead.map(p=>[p.name,p.stock])];const csv=rows.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`godown-complete-report-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url);};
document.querySelector('#excel-import').addEventListener('change',async e=>{e.preventDefault();e.stopImmediatePropagation();const file=e.target.files[0];e.target.value='';if(!file||!window.XLSX)return;const rows=XLSX.utils.sheet_to_json(XLSX.read(await file.arrayBuffer(),{type:'array'}).Sheets[XLSX.read(await file.arrayBuffer(),{type:'array'}).SheetNames[0]],{defval:''});let imported=0;rows.forEach(row=>{const name=String(findColumn(row,['product','item','productname','itemname','description'])).trim();if(!name)return;const category=String(findColumn(row,['category','group','productcategory'])).trim()||'Uncategorized',code=String(findColumn(row,['code','sku','itemcode','productcode'])).trim()||`IMPORT-${Date.now()}-${imported}`,variant=String(findColumn(row,['variant','size','finish','sizefinish','model'])).trim()||'Standard',price=Math.max(0,Number(findColumn(row,['price','rate','unitprice','priceperpiece','mrp','cost']))||0),stock=Math.max(0,Number(findColumn(row,['stock','qty','quantity','pieces','closingstock','openingstock']))||0),min=Math.max(0,Number(findColumn(row,['minimum','minstock','alert','alertat']))||0);let product=products.find(p=>p.name.toLowerCase()===name.toLowerCase()&&p.category.toLowerCase()===category.toLowerCase()&&p.code.toLowerCase()===code.toLowerCase()&&p.variant.toLowerCase()===variant.toLowerCase());if(product){const oldPrice=product.price||0;if(price&&price!==oldPrice){recordPriceChange(product,oldPrice,price,'Excel import');product.price=price}const before=product.stock;product.stock+=stock;activity.unshift({type:'in',product:product.name,category,code,variant,price,transactionPrice:price,qty:stock,beforeStock:before,afterStock:product.stock,stockChange:stock,ref:'Excel import',time:'Just now'})}else{product={id:Date.now()+imported,name,category,code,variant,stock,price,min};products.push(product);activity.unshift({type:'in',product:name,category,code,variant,price,transactionPrice:price,qty:stock,beforeStock:0,afterStock:stock,stockChange:stock,ref:'Excel import',time:'Just now'})}imported++});save();render();alert(`${imported} products imported.`)},true);
